from PIL import Image
import numpy as np
im = np.array(Image.open('mol_0234.png').convert('L'))
def widths(x0,y0,x1,y1,thr=128):
    sub = im[y0:y1, x0:x1] < thr
    for i,row in enumerate(sub):
        xs = np.where(row)[0]
        if len(xs): print(y0+i, xs.min()+x0, xs.max()+x0, len(xs))
        else: print(y0+i, '-')
print('--- top Me bond (x 290-340, y 90-160)')
widths(285,90,345,165)
